		MinIdleConns:    configuration.GetInt(prefix + "min_idle_conns"),
		MaxIdleConns:    configuration.GetInt(prefix + "max_idle_conns"),
		ConnMaxIdleTime: seconds(configuration, prefix+"conn_max_idle_time_seconds"),
