201			glog.V(4).InfofCtx(ctx, "UpdateEntry %s has HardLinkId %x counter=%d",
202				entry.FullPath, entry.HardLinkId, entry.HardLinkCounter)
203		}
204	
205		if err := fsw.handleUpdateToHardLinks(ctx, entry); err != nil {
206			return err
207		}
208	
209		return actualStore.UpdateEntry(ctx, entry)
210	}
640		// but the acknowledged state still reflects everything at or below this.
641		logTsNs := time.Now().UnixNano()
642	
643		entry, err := fs.filer.FindEntry(ctx, lockPath)
644		if err != nil {
645			return &filer_pb.UpdateEntryResponse{}, fmt.Errorf("not found %s: %v", fullpath, err)
646		}
647		if err := validateUpdateEntryPreconditions(entry, req.ExpectedExtended); err != nil {
648			return &filer_pb.UpdateEntryResponse{}, err
649		}
650		if conditionIsSet(req.Condition) && !writeConditionSatisfied(req.Condition, entry) {
651			glog.V(3).InfofCtx(ctx, "UpdateEntry %s: precondition failed: %v", fullpath, req.Condition)
652			return &filer_pb.UpdateEntryResponse{}, status.Errorf(codes.FailedPrecondition, "precondition failed: %s", fullpath)
653		}
654	
655		chunks, garbage, err2 := fs.cleanupChunks(ctx, fullpath, entry, req.Entry)
656		if err2 != nil {
657			return &filer_pb.UpdateEntryResponse{}, fmt.Errorf("UpdateEntry cleanupChunks %s: %v", fullpath, err2)
658		}
659	
660		newEntry := filer.FromPbEntry(req.Directory, req.Entry)
661		newEntry.Chunks = chunks
662	
663		// Don't apply TTL to remote entries - they're managed by remote storage
664		if newEntry.Remote != nil {
665			newEntry.TtlSec = 0
666		}
667	
668		if filer.EqualEntry(entry, newEntry) {
669			return &filer_pb.UpdateEntryResponse{LogTsNs: logTsNs, LogSignature: fs.filer.Signature}, err
670		}
671	
672		ctx, eventSink := filer.WithMetadataEventSink(ctx)
673		resp := &filer_pb.UpdateEntryResponse{LogTsNs: logTsNs, LogSignature: fs.filer.Signature}
674		if err = fs.filer.UpdateEntry(ctx, entry, newEntry); err == nil {
675			fs.filer.DeleteChunksNotRecursive(garbage)
676	
677			fs.filer.NotifyUpdateEvent(ctx, entry, newEntry, true, req.IsFromOtherCluster, req.Signatures)
678			resp.MetadataEvent = eventSink.Last()
679	
680		} else {
418	)
