420	func (f *Filer) FindEntry(ctx context.Context, p util.FullPath) (entry *Entry, err error) {
421	
422		if string(p) == "/" {
423			return Root, nil
424		}
425		entry, err = f.Store.FindEntry(ctx, p)
426		if entry != nil && entry.TtlSec > 0 {
427			if entry.IsExpireS3Enabled() {
428				if entry.GetS3ExpireTime().Before(time.Now()) && !entry.IsS3Versioning() {
429					if delErr := f.doDeleteEntryMetaAndData(ctx, entry, true, false, nil); delErr != nil {
430						glog.ErrorfCtx(ctx, "FindEntry doDeleteEntryMetaAndData %s failed: %v", entry.FullPath, delErr)
431					}
432					return nil, filer_pb.ErrNotFound
433				}
434			} else if entry.Crtime.Add(time.Duration(entry.TtlSec) * time.Second).Before(time.Now()) {
435				f.Store.DeleteOneEntry(ctx, entry)
436				return nil, filer_pb.ErrNotFound
437			}
438		}
439	
440		if entry == nil && (err == nil || errors.Is(err, filer_pb.ErrNotFound)) {
441			if lazy, lazyErr := f.maybeLazyFetchFromRemote(ctx, p); lazyErr != nil {
442				glog.V(1).InfofCtx(ctx, "FindEntry lazy fetch %s: %v", p, lazyErr)
443			} else if lazy != nil {
444				return lazy, nil
445			}
446		}
447	
448		return entry, err
449	}
